import { z } from 'zod'
import { generateSchedule, type ScheduledInvoice } from '@/lib/billing'
import { badRequest, forbidden, notFound, withRetry } from '@/lib/errors'
import { prisma } from '@/lib/prisma'
import { loadCaller, requireLeaseAccess, requireMember } from '@/server/access'
import {
  compareAllocationOrder,
  isoDateToDb,
  paidByInvoice,
  serializeInvoice,
  serializeLease,
  serializePayment,
  type InvoiceDto,
  type LeaseDto,
  type PaymentDto,
  type ServiceCtx,
} from './serialize'

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/

const createLeaseSchema = z
  .object({
    unitId: z.string().uuid(),
    tenantId: z.string().uuid(),
    startDate: z.string().regex(ISO_DATE, 'must be YYYY-MM-DD'),
    endDate: z.string().regex(ISO_DATE, 'must be YYYY-MM-DD'),
    monthlyRentSen: z.number().int().positive(),
    depositSen: z.number().int().nonnegative(),
  })
  .strict()

export type CreateLeaseInput = z.infer<typeof createLeaseSchema>

// D2 order for POST /api/leases: the route calls this before reading the body, so a non-manager gets 403
// even when the body is malformed JSON. createLease repeats the check, so it is safe to call alone.
export async function requireLeaseCreator(ctx: ServiceCtx): Promise<void> {
  requireMember(await loadCaller(ctx.userId), ['manager'])
}

export async function createLease(ctx: ServiceCtx, input: unknown): Promise<{ id: string }> {
  const caller = await loadCaller(ctx.userId)
  // POST /api/leases has no target record yet, so the role check (403) precedes body validation (400).
  const { orgId } = requireMember(caller, ['manager'])
  const body = createLeaseSchema.parse(input)

  // R11/R46: the schedule comes only from billing.ts; its validation errors are the 400 message.
  let schedule: ScheduledInvoice[]
  try {
    schedule = generateSchedule(body)
  } catch (e) {
    throw badRequest(e instanceof Error ? e.message : 'Invalid lease')
  }

  // R39/D15: body ids are untrusted; a unit or tenant outside the caller's org is a 404, exactly like a
  // nonexistent one, so another org's ids are never confirmed. The composite FKs enforce the same in the DB.
  const [unit, tenant] = await Promise.all([
    prisma.units.findFirst({ where: { id: body.unitId, org_id: orgId }, select: { id: true } }),
    prisma.tenants.findFirst({ where: { id: body.tenantId, org_id: orgId }, select: { id: true } }),
  ])
  if (!unit) throw notFound('Unit not found')
  if (!tenant) throw notFound('Tenant not found')

  // R46: lease + exactly the scheduled invoices + audit row commit together or not at all. Overlap is
  // enforced by the leases_no_overlap EXCLUDE constraint (D16): a concurrent overlapping insert waits,
  // then fails with 23P01, which errors.ts maps to 409. withRetry covers a deadlock (40P01) once.
  return withRetry(() =>
    prisma.$transaction(async (tx) => {
      const lease = await tx.leases.create({
        data: {
          org_id: orgId,
          unit_id: body.unitId,
          tenant_id: body.tenantId,
          start_date: isoDateToDb(body.startDate),
          end_date: isoDateToDb(body.endDate),
          monthly_rent_sen: body.monthlyRentSen,
          deposit_sen: body.depositSen,
          created_by: caller.userId,
        },
        select: { id: true },
      })
      await tx.invoices.createMany({
        data: schedule.map((inv) => ({
          org_id: orgId,
          lease_id: lease.id,
          kind: inv.kind,
          period_index: inv.periodIndex,
          period_start: inv.periodStart === null ? null : isoDateToDb(inv.periodStart),
          period_end: inv.periodEnd === null ? null : isoDateToDb(inv.periodEnd),
          due_date: isoDateToDb(inv.dueDate),
          amount_sen: inv.amountSen,
        })),
      })
      await tx.audit_log.create({
        data: {
          org_id: orgId,
          actor_id: caller.userId,
          action: 'lease.created',
          entity_id: lease.id,
          details: {
            unitId: body.unitId,
            tenantId: body.tenantId,
            startDate: body.startDate,
            endDate: body.endDate,
            monthlyRentSen: body.monthlyRentSen,
            depositSen: body.depositSen,
            invoiceCount: schedule.length,
          },
        },
      })
      return { id: lease.id }
    }),
  )
}

export type LeaseDetail = { lease: LeaseDto; invoices: InvoiceDto[]; payments: PaymentDto[] }

// GET /api/leases/:leaseId, the brief's shape exactly. asOf drives the overdue status (R17).
export async function getLease(ctx: ServiceCtx, leaseId: string, asOf: Date = new Date()): Promise<LeaseDetail> {
  const caller = await loadCaller(ctx.userId)
  const lease = await requireLeaseAccess(caller, leaseId, ['manager', 'staff', 'tenant'])
  // Every query is scoped by the checked lease's own org_id as well as its id (D18).
  const scope = { lease_id: lease.id, org_id: lease.org_id }
  const [invoiceRows, allocationSums, paymentRows] = await Promise.all([
    prisma.invoices.findMany({ where: scope }),
    prisma.payment_allocations.groupBy({ by: ['invoice_id'], where: scope, _sum: { amount_sen: true } }),
    prisma.payments.findMany({ where: scope, orderBy: [{ received_at: 'asc' }, { created_at: 'asc' }, { id: 'asc' }] }),
  ])
  // Voiding deletes that payment's allocations (D14), so every remaining allocation counts as paid.
  const paid = paidByInvoice(allocationSums)
  const invoices = invoiceRows.map((row) => serializeInvoice(row, paid.get(row.id) ?? 0, asOf)).sort(compareAllocationOrder)
  return { lease: serializeLease(lease), invoices, payments: paymentRows.map(serializePayment) }
}

export type LeaseListItem = LeaseDto & { unitName: string; tenantName: string }

// Leases list for the UI: staff/manager see their org's leases; a tenant sees only their own.
export async function listLeases(ctx: ServiceCtx): Promise<LeaseListItem[]> {
  const caller = await loadCaller(ctx.userId)
  const or: ({ org_id: string } | { tenant_id: { in: string[] } })[] = []
  if (caller.member) or.push({ org_id: caller.member.orgId })
  if (caller.tenantIds.length > 0) or.push({ tenant_id: { in: caller.tenantIds } })
  if (or.length === 0) throw forbidden()
  const rows = await prisma.leases.findMany({
    where: { OR: or },
    include: { units: { select: { name: true } }, tenants: { select: { full_name: true } } },
    orderBy: [{ start_date: 'asc' }, { id: 'asc' }],
  })
  return rows
    .map((row) => ({ ...serializeLease(row), unitName: row.units.name, tenantName: row.tenants.full_name }))
    .sort((a, b) => (a.unitName === b.unitName ? 0 : a.unitName < b.unitName ? -1 : 1))
}
import { toMytDate } from '@/lib/billing'
import { isYearMonth } from '@/lib/dates'
import { badRequest } from '@/lib/errors'
import { toSen } from '@/lib/money'
import { prisma } from '@/lib/prisma'
import { loadCaller, requireMember } from '@/server/access'
import { isoDateToDb, paidByInvoice, serializeInvoice, type ServiceCtx } from './serialize'

// D49: 100 years still bounds generate_series without rejecting any realistic range.
const MAX_MONTHS = 1200

export type CollectionsRow = { month: string; collectedSen: number }

function monthIndex(ym: string): number {
  return Number(ym.slice(0, 4)) * 12 + Number(ym.slice(5, 7)) - 1
}

// GET /api/reports/collections: approved payments summed per Malaysia calendar month of received_at.
export async function collectionsReport(ctx: ServiceCtx, from: string, to: string): Promise<CollectionsRow[]> {
  const caller = await loadCaller(ctx.userId)
  const { orgId } = requireMember(caller, ['manager', 'staff'])
  // Bounded so one request cannot ask Postgres for an arbitrarily long series.
  if (!isYearMonth(from) || !isYearMonth(to) || from > to || monthIndex(to) - monthIndex(from) + 1 > MAX_MONTHS) {
    throw badRequest('Invalid range')
  }
  // D25: generate_series gives every month in [from, to] so empty months appear as 0 (brief R29). The
  // series is built on timestamp WITHOUT time zone, so the session TimeZone never shifts a month. A
  // payment's month is its received_at in Asia/Kuala_Lumpur (R3), not UTC: 2026-03-01 00:30 MYT is March.
  // sum(bigint) is numeric, cast back to bigint; toSen turns it into a safe JS number (D3).
  const rows = await prisma.$queryRaw<{ month: string; collected_sen: bigint }[]>`
    with months as (
      select generate_series(
        to_date(${from}, 'YYYY-MM')::timestamp,
        to_date(${to}, 'YYYY-MM')::timestamp,
        interval '1 month'
      ) as m
    ),
    collected as (
      select to_char(p.received_at at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM') as month,
             sum(p.amount_sen) as total
      from public.payments p
      where p.org_id = ${orgId}::uuid
        and p.status = 'approved'
      group by 1
    )
    select to_char(months.m, 'YYYY-MM') as month,
           coalesce(collected.total, 0)::bigint as collected_sen
    from months
    left join collected on collected.month = to_char(months.m, 'YYYY-MM')
    order by months.m`
  return rows.map((r) => ({ month: r.month, collectedSen: toSen(r.collected_sen) }))
}

// Dashboard: number of the org's invoices whose computed status (billing.ts, R27) is overdue at asOf.
export async function overdueCount(ctx: ServiceCtx, asOf: Date): Promise<number> {
  const caller = await loadCaller(ctx.userId)
  const { orgId } = requireMember(caller, ['manager', 'staff'])
  // Prefilter only (an invoice cannot be overdue before its due date has passed in MYT, D5); the
  // decision itself is invoiceStatus, so there is a single definition of overdue.
  const candidates = await prisma.invoices.findMany({
    where: { org_id: orgId, due_date: { lt: isoDateToDb(toMytDate(asOf)) } },
  })
  if (candidates.length === 0) return 0
  const sums = await prisma.payment_allocations.groupBy({
    by: ['invoice_id'],
    where: { org_id: orgId, invoice_id: { in: candidates.map((c) => c.id) } },
    _sum: { amount_sen: true },
  })
  const paid = paidByInvoice(sums)
  return candidates.filter((row) => serializeInvoice(row, paid.get(row.id) ?? 0, asOf).status === 'overdue').length
}
import type { invoices, leases, payments } from '@/generated/prisma/client'
import { invoiceStatus, type InvoiceKind, type InvoiceStatus } from '@/lib/billing'
import { dateToIso, formatInstantMyt } from '@/lib/dates'
import { toSen } from '@/lib/money'

// Every service takes the verified caller id only; role and org are always re-read from the DB (R37).
export type ServiceCtx = { userId: string }

export type PaymentMethod = 'cash' | 'bank_transfer' | 'online'
export type PaymentStatus = 'pending_verification' | 'approved' | 'rejected' | 'voided'

export type LeaseDto = {
  id: string
  unitId: string
  tenantId: string
  startDate: string
  endDate: string
  monthlyRentSen: number
  depositSen: number
}

export type InvoiceDto = {
  id: string
  kind: InvoiceKind
  periodIndex: number | null
  periodStart: string | null
  periodEnd: string | null
  dueDate: string
  amountSen: number
  paidSen: number
  status: InvoiceStatus
}

export type PaymentDto = {
  id: string
  amountSen: number
  unappliedSen: number
  method: PaymentMethod
  status: PaymentStatus
  receivedAt: string
}

// "YYYY-MM-DD" -> the UTC-midnight Date Prisma expects for a @db.Date column (inverse of dateToIso).
export function isoDateToDb(iso: string): Date {
  const d = new Date(`${iso}T00:00:00.000Z`)
  if (Number.isNaN(d.getTime()) || dateToIso(d) !== iso) throw new Error('Invalid calendar date')
  return d
}

// DB CHECK constraints pin these columns; a value outside them means the schema drifted, so fail loudly.
function asKind(v: string): InvoiceKind {
  if (v === 'deposit' || v === 'rent') return v
  throw new Error('Unexpected invoice kind')
}

function asMethod(v: string): PaymentMethod {
  if (v === 'cash' || v === 'bank_transfer' || v === 'online') return v
  throw new Error('Unexpected payment method')
}

export function asPaymentStatus(v: string): PaymentStatus {
  if (v === 'pending_verification' || v === 'approved' || v === 'rejected' || v === 'voided') return v
  throw new Error('Unexpected payment status')
}

type LeaseRow = Pick<leases, 'id' | 'unit_id' | 'tenant_id' | 'start_date' | 'end_date' | 'monthly_rent_sen' | 'deposit_sen'>
type InvoiceRow = Pick<invoices, 'id' | 'kind' | 'period_index' | 'period_start' | 'period_end' | 'due_date' | 'amount_sen'>
type PaymentRow = Pick<payments, 'id' | 'amount_sen' | 'unapplied_sen' | 'method' | 'status' | 'received_at'>

export function serializeLease(row: LeaseRow): LeaseDto {
  return {
    id: row.id,
    unitId: row.unit_id,
    tenantId: row.tenant_id,
    startDate: dateToIso(row.start_date),
    endDate: dateToIso(row.end_date),
    monthlyRentSen: toSen(row.monthly_rent_sen),
    depositSen: toSen(row.deposit_sen),
  }
}

// R27: paid = sum of allocations; status is computed with billing.ts at read time, never stored.
export function serializeInvoice(row: InvoiceRow, paidSen: number, asOf: Date): InvoiceDto {
  const dueDate = dateToIso(row.due_date)
  const amountSen = toSen(row.amount_sen)
  return {
    id: row.id,
    kind: asKind(row.kind),
    periodIndex: row.period_index,
    periodStart: row.period_start ? dateToIso(row.period_start) : null,
    periodEnd: row.period_end ? dateToIso(row.period_end) : null,
    dueDate,
    amountSen,
    paidSen,
    status: invoiceStatus({ dueDate, amountSen, paidSen }, asOf),
  }
}

export function serializePayment(row: PaymentRow): PaymentDto {
  return {
    id: row.id,
    amountSen: toSen(row.amount_sen),
    unappliedSen: toSen(row.unapplied_sen),
    method: asMethod(row.method),
    status: asPaymentStatus(row.status),
    receivedAt: formatInstantMyt(row.received_at),
  }
}

// R26: allocation order = due date, then deposit before rent, then period index (deposit has none).
// The same order private.allocate_payment uses, so the page lists invoices in the order they fill.
export function compareAllocationOrder(a: InvoiceDto, b: InvoiceDto): number {
  if (a.dueDate !== b.dueDate) return a.dueDate < b.dueDate ? -1 : 1
  if (a.kind !== b.kind) return a.kind === 'deposit' ? -1 : 1
  return (a.periodIndex ?? -1) - (b.periodIndex ?? -1)
}

// Sums allocation rows (from a Prisma groupBy) into invoice_id -> paid sen.
export function paidByInvoice(rows: { invoice_id: string; _sum: { amount_sen: bigint | null } }[]): Map<string, number> {
  const map = new Map<string, number>()
  for (const r of rows) map.set(r.invoice_id, r._sum.amount_sen === null ? 0 : toSen(r._sum.amount_sen))
  return map
}

