import { readFileSync } from "node:fs";

const envText = readFileSync("/home/electronica-care/ezy-prep/exam/app/.env.local", "utf8");
const env = Object.fromEntries(
  envText.split("\n").filter((l) => l.includes("=") && !l.startsWith("#")).map((l) => {
    const i = l.indexOf("=");
    return [l.slice(0, i).trim(), l.slice(i + 1).trim().replace(/^"|"$/g, "")];
  }),
);
const url = env.NEXT_PUBLIC_SUPABASE_URL;
const key = env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
const base = "http://127.0.0.1:3000";

async function cookieFor(email) {
  const r = await fetch(`${url}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: key, "content-type": "application/json" },
    body: JSON.stringify({ email, password: "RentDemo#2026" }),
  });
  const session = await r.json();
  const name = `sb-${new URL(url).hostname.split(".")[0]}-auth-token`;
  return `${name}=base64-${Buffer.from(JSON.stringify(session)).toString("base64url")}`;
}

const who = process.argv[2] ?? "manager@northwind.test";
const cookie = await cookieFor(who);
const paths = process.argv.slice(3);
